/**
 * @brief Schedule the function's entry first and follow unplaced successors to
 * encourage fallthrough.
 *
 * @param fn IR function being analyzed or emitted.
 * @param order Output array of block IDs in emission order.
 * @param seen Scratch flags for blocks already scheduled.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Allocate a frame only when the startup function uses it.
// Place reachable blocks along unvisited successor paths for cheap
// fallthrough.
static void cg_order_blocks(const IrFunction* fn,
                            IrBlockId* order,
                            bool* seen) {
  size_t count = fn->blocks.count;
  memset(seen, 0, count * sizeof(*seen));
  IrBlockId next = fn->entrypoint;
  for (size_t i = 0, first_unplaced = 0; i < count; i++) {
    if (next == IR_INVALID_ID || seen[next]) {
while (seen[first_unplaced])
        first_unplaced++;
      next = first_unplaced;
    }
    // Follow an unplaced successor where possible so codegen can use
    // fallthrough.
    IrBlockId current = next;
    order[i] = current;
    seen[current] = true;
    const IrBlockTerminator* term = &fn->blocks.data[current].terminator;
    next = IR_INVALID_ID;
    if (term->type == IR_TERMINATOR_JUMP) {
      next = term->value.jump_target;
    } else if (term->type == IR_TERMINATOR_CONDITIONAL) {
      IrBlockId yes = term->value.conditional_target.true_target;
      IrBlockId no = term->value.conditional_target.false_target;
      if (no == current + 1 && !seen[no]) {
        next = no;
      } else {
        next = seen[yes] ? no : yes;
      }
    }
  }
}

void cg_generate_function(Ctx* ctx,
                          FILE* out,
                          IrFunction* fn,
                          bool direct_entry) {
  fputs("LABEL $$", out);
  fputs(fn->name, out);
  cg_print_nl(out);
  if (!direct_entry) {
    fputs("PUSHFRAME", out);
    cg_print_nl(out);
  }

  // AI generated by: Codex (GPT-6.2-sol)
  // Prompt: "Implement all"
  // Changes: Omit the return variable for the stack convention.
  IrFunctionId fid = (IrFunctionId)(fn - ctx->ir.functions.data);
  if (fn->return_type != IR_UNIT && !cg_uses_stack_return(ctx, fid)) {
    fputs("DEFVAR LF@%ret", out);
    cg_print_nl(out);
  }

  // AI generated by: Codex (GPT-6.2-sol)
  // Prompt: "Implement all"
  // Changes: Declare only surviving values and referenced local slots.
  size_t* uses = TRY_MALLOC((fn->value_count + 1) * sizeof(*uses));
  optimizer_count_value_uses(fn, uses);
  size_t storage_count = fn->value_count + fn->slots.count;
  bool* storage =
      TRY_MALLOC_OR((storage_count + 1) * sizeof(*storage), { free(uses); });
  // AI generated by: Codex (GPT-6.2-sol)
  // Prompt: "Implement all"
  // Changes: Allocate explicit placement for real values and aliased slots.
  CgPlacement* placement =
      TRY_MALLOC_OR((fn->value_count + 1) * sizeof(*placement), {
        free(storage);
        free(uses);
      });
  for (IrValueId value = 0; value < fn->value_count; value++) {
    placement[value] = (CgPlacement){.slot = IR_INVALID_ID, .local = value};
  }

  // AI generated by: Codex (GPT-6.2-sol)
  // Prompt: "Implement. You can change IR if it improves the results/makes things more clear. Also try to split long files (300+) into smaller thematic ones, like optimizer was before"
  // Changes: Plan all writes before checking which loaded snapshots can alias their slots.
  unsigned char* visited = TRY_MALLOC_OR(fn->blocks.count + 1, {
    free(placement);
    free(storage);
    free(uses);
  });
  // A producer placed directly in a slot can overwrite a captured load
  // even if the corresponding IR store will emit no instruction.
  for (IrBlockId b = 0; b < fn->blocks.count; b++)
    cg_plan_stores(fn, &fn->blocks.data[b], uses, placement);

for (IrBlockId b = 0; b < fn->blocks.count; b++)
    cg_plan_loads(fn, b, uses, placement, visited);
  free(visited);
  memset(storage, 0, storage_count * sizeof(*storage));
  for (size_t b = 0; b < fn->blocks.count; b++) {
    IrBlock* block = &fn->blocks.data[b];
    cg_reuse_locals(block, uses, placement);
    IrInstruction* comparison = cg_branch_comparison(fn, block, uses);
    IrInstructionArray* instructions = &block->instructions;
    for (size_t i = 0; i < instructions->count; i++) {
      IrInstruction* inst = &instructions->data[i];
if (inst == comparison &&
          (inst->type == IR_INST_EQ || inst->type == IR_INST_NE))
        continue;
if (inst->result != IR_INVALID_ID &&
          placement[inst->result].slot == IR_INVALID_ID)
        storage[placement[inst->result].local] = true;
      if (inst->type == IR_INST_LOAD) {
        storage[fn->value_count + inst->operands.load.source] = true;
      }
      if (inst->type == IR_INST_STORE) {
        storage[fn->value_count + inst->operands.store.target] = true;
      }
    }
  }

  // AI generated by: Codex (GPT-6.2-sol)
  // Prompt: "Implement all"
  // Changes: Create a local frame at startup only if an emitted operand needs
  // it.
  if (direct_entry) {
    for (size_t i = 0; i < storage_count; i++) {
      if (storage[i]) {
        fputs("CREATEFRAME\nPUSHFRAME\n", out);
        break;
      }
    }
  }

  for (size_t i = 0; i < fn->value_count; i++) {
    if (!storage[i])
      continue;
    fputs("DEFVAR ", out);
    cg_print_localframe_val(out, i);
    cg_print_nl(out);
  }

  for (size_t i = fn->parameter_count; i < fn->slots.count; i++) {
    if (!storage[fn->value_count + i])
      continue;
    fputs("DEFVAR ", out);
    cg_print_localframe_slot(out, i);
    cg_print_nl(out);
  }
  free(storage);

  // Pass the next block in emission order, which can differ from the next
  // numerical block ID.
  // AI generated by: Codex (GPT-6.2-sol)
  // Prompt: "Implement all"
  // Changes: Emit blocks in the planned order and describe actual fallthrough
  // to each branch.
  size_t block_count = fn->blocks.count;
  IrBlockId* order = TRY_MALLOC_OR((block_count + 1) * sizeof(*order), {
    free(placement);
    free(uses);
  });
  bool* seen = TRY_MALLOC_OR((block_count + 1) * sizeof(*seen), {
    free(order);
    free(placement);
    free(uses);
  });
  cg_order_blocks(fn, order, seen);
  free(seen);
  for (size_t i = 0; i < block_count; i++) {
    IrBlockId bid = order[i];
    IrBlockId next = i + 1 < block_count ? order[i + 1] : IR_INVALID_ID;
    IrBlock* block = &fn->blocks.data[bid];
    cg_generate_block(ctx, out, placement, fn, bid, next, block,
                      cg_branch_comparison(fn, block, uses), direct_entry);
  }
  free(order);
  free(placement);
  free(uses);
}
